dir:


































  &DefaultButton;




function dir$dmdvxd(p){
  this.constructor(p);
}
dir$dmdvxd.prototype = new DirEvent();
dir$dmdvxd.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmdvxd.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

dir$dmdvxdDisabledMasterField(p, g);

}

function dir$dmdvxdDisabledMasterField(p, g){

  if(p.valForm('ma_dv').trim() != '')
  {
    p.setDisabled('ma_dv', true);
  }
  else
  {
    p.setDisabled('ma_dv', false);
  }
}






	.control-label.ma_dv, .control-label.ten_dv
	{	

		color: #499b98;;
	}







declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã đơn vị đã tồn tại' else N'Units code is exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã đơn vị đã tồn tại' else N'Units code is exists' end
